"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["6791"],{1262(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>h,frontMatter:()=>o,contentTitle:()=>a,toc:()=>d,assets:()=>l});var s=JSON.parse('{"id":"DevOps/devops-culture","title":"DevOps Culture and Metrics","description":"Before the tools, the ideas. This page covers the frameworks that explain why DevOps practices exist and how to measure whether they\'re working.","source":"@site/docs/DevOps/01-devops-culture.md","sourceDirName":"DevOps","slug":"/DevOps/devops-culture","permalink":"/Mindstack/docs/DevOps/devops-culture","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"title":"DevOps Culture and Metrics","sidebar_label":"DevOps Culture","sidebar_position":1},"sidebar":"devopsSidebar","previous":{"title":"Overview","permalink":"/Mindstack/docs/DevOps/overview"},"next":{"title":"Bash for DevOps","permalink":"/Mindstack/docs/DevOps/bash-for-devops"}}'),r=t(4848),i=t(8453);let o={title:"DevOps Culture and Metrics",sidebar_label:"DevOps Culture",sidebar_position:1},a="DevOps Culture and Metrics",l={},d=[{value:"CALMS Framework",id:"calms-framework",level:2},{value:"The DevOps Lifecycle (Infinite Loop)",id:"the-devops-lifecycle-infinite-loop",level:2},{value:"DORA Metrics \u2014 Measuring DevOps Performance",id:"dora-metrics--measuring-devops-performance",level:2},{value:"DevOps vs SRE vs Platform Engineering",id:"devops-vs-sre-vs-platform-engineering",level:2},{value:"The Three Ways (from &quot;The Phoenix Project&quot;)",id:"the-three-ways-from-the-phoenix-project",level:2},{value:"Blameless Postmortems",id:"blameless-postmortems",level:2},{value:"Error Budgets (SRE Concept)",id:"error-budgets-sre-concept",level:2},{value:"Shift-Left",id:"shift-left",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function c(e){let n={code:"code",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"devops-culture-and-metrics",children:"DevOps Culture and Metrics"})}),"\n",(0,r.jsxs)(n.p,{children:["Before the tools, the ideas. This page covers the frameworks that explain ",(0,r.jsx)(n.em,{children:"why"})," DevOps practices exist and how to measure whether they're working."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"calms-framework",children:"CALMS Framework"}),"\n",(0,r.jsx)(n.p,{children:"The five pillars of DevOps culture (coined by Damon Edwards and John Willis):"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"C \u2014 Culture\n  Shared ownership between Dev and Ops\n  Blameless postmortems (focus on systems, not individuals)\n  Psychological safety to report failures early\n\nA \u2014 Automation\n  Automate the repeatable: builds, tests, deployments, infrastructure\n  Manual steps are a source of human error and a bottleneck\n\nL \u2014 Lean\n  Small batch sizes \u2014 ship small changes frequently, not big-bang releases\n  Eliminate waste (waiting, handoffs, unnecessary process)\n\nM \u2014 Measurement\n  You can't improve what you don't measure\n  Track deployment frequency, lead time, failure rate, recovery time (see DORA below)\n\nS \u2014 Sharing\n  Knowledge sharing across teams \u2014 no silos\n  Shared tools, shared dashboards, shared on-call responsibilities\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"the-devops-lifecycle-infinite-loop",children:"The DevOps Lifecycle (Infinite Loop)"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'        \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510     \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510     \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510     \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n        \u2502  PLAN   \u2502\u2500\u2500\u2500\u2500\u25B6\u2502  CODE   \u2502\u2500\u2500\u2500\u2500\u25B6\u2502  BUILD  \u2502\u2500\u2500\u2500\u2500\u25B6\u2502  TEST   \u2502\n        \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518     \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518     \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518     \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n             \u25B2                                                \u2502\n             \u2502                                                \u25BC\n        \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510     \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510     \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510     \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n        \u2502 MONITOR \u2502\u25C0\u2500\u2500\u2500\u2500\u2502 OPERATE \u2502\u25C0\u2500\u2500\u2500\u2500\u2502 DEPLOY  \u2502\u25C0\u2500\u2500\u2500\u2500\u2502 RELEASE \u2502\n        \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518     \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518     \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518     \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\nEach stage has a "class" of tools (see the toolchain map in the overview page).\nThe loop never truly ends \u2014 monitoring feeds back into planning the next change.\n'})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"dora-metrics--measuring-devops-performance",children:"DORA Metrics \u2014 Measuring DevOps Performance"}),"\n",(0,r.jsx)(n.p,{children:"DORA (DevOps Research and Assessment, now part of Google Cloud) identified four key metrics that correlate with high-performing engineering teams."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"1. Deployment Frequency\n   How often do you deploy to production?\n   Elite:  multiple times per day\n   High:   once per day to once per week\n   Medium: once per week to once per month\n   Low:    less than once per month\n\n2. Lead Time for Changes\n   How long from code committed to code running in production?\n   Elite:  less than one hour\n   High:   one day to one week\n   Medium: one week to one month\n   Low:    more than one month\n\n3. Change Failure Rate\n   What percentage of deployments cause a failure in production?\n   Elite:  0-15%\n   High:   16-30%\n   Medium/Low: higher\n\n4. Time to Restore Service (MTTR)\n   How long does it take to recover from a failure in production?\n   Elite:  less than one hour\n   High:   less than one day\n   Medium: less than one week\n   Low:    more than one week\n"})}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Why these four:\n  They balance SPEED (frequency, lead time) against STABILITY (failure rate, MTTR)\n  High performers are fast AND stable \u2014 it's not a tradeoff, contrary to intuition\n  Elite performers deploy more often AND have fewer failures than low performers\n\nTools to measure DORA metrics:\n  GitHub: built-in insights + third-party (LinearB, Sleuth, Haystack)\n  GitLab: built-in DevOps Score / Value Stream Analytics\n  Custom: combine CI/CD data + incident tracking (PagerDuty, Opsgenie)\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"devops-vs-sre-vs-platform-engineering",children:"DevOps vs SRE vs Platform Engineering"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'DevOps:\n  A culture/philosophy \u2014 "Dev and Ops share responsibility"\n  Not a specific job (though the title is common in practice)\n  Focuses on: breaking down silos, automating the pipeline\n\nSRE (Site Reliability Engineering):\n  Google\'s specific implementation of DevOps principles\n  Treats operations as a software engineering problem\n  Introduces: SLIs/SLOs/SLAs, error budgets, blameless postmortems\n  "Class of problems that DevOps describes, SRE solves with software engineering"\n\nPlatform Engineering:\n  Building internal developer platforms (IDPs) \u2014 self-service infrastructure\n  Goal: developers deploy without needing to know Kubernetes/Terraform details\n  Tools: Backstage (Spotify), Crossplane, internal CLI tools\n  Emerged because "everyone learns Kubernetes" doesn\'t scale organizationally\n\nRelationship:\n  DevOps = the philosophy\n  SRE = one rigorous implementation (heavy on metrics and error budgets)\n  Platform Engineering = productising DevOps/SRE practices as an internal product\n'})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"the-three-ways-from-the-phoenix-project",children:'The Three Ways (from "The Phoenix Project")'}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"First Way \u2014 Flow:\n  Work flows left to right (Dev \u2192 Ops \u2192 Customer) as fast as possible\n  Practices: CI/CD, small batch sizes, eliminate handoff delays,\n             limit work in progress (WIP)\n\nSecond Way \u2014 Feedback:\n  Fast feedback flows right to left (Ops \u2192 Dev)\n  Practices: automated testing, monitoring/alerting, shift-left security,\n             production telemetry visible to developers\n\nThird Way \u2014 Continual Learning and Experimentation:\n  A culture of experimentation, risk-taking, and learning from failure\n  Practices: blameless postmortems, dedicated time for improvement,\n             game days / chaos engineering\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"blameless-postmortems",children:"Blameless Postmortems"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"When an incident happens, the goal is to understand WHAT happened\nand WHY the system allowed it \u2014 never WHO caused it.\n\nPostmortem document structure:\n  1. Summary \u2014 what happened, in one paragraph\n  2. Impact \u2014 who/what was affected, for how long\n  3. Timeline \u2014 detailed sequence of events (detection, response, resolution)\n  4. Root cause \u2014 the underlying systemic cause (5 Whys technique)\n  5. Action items \u2014 specific, assigned, time-bound follow-ups\n  6. Lessons learned \u2014 what worked, what didn't\n\n5 Whys example:\n  Problem: Production database ran out of disk space\n  Why? Log files filled the disk\n  Why? Log rotation wasn't configured\n  Why? The deployment script for this service predates the log rotation standard\n  Why? No process exists to audit old services against new standards\n  Why? No automated compliance checking in the platform\n  \u2192 Root cause: missing automated infrastructure compliance checking\n  \u2192 Action item: add disk-usage alerting + audit all services for log rotation config\n\nWhy blameless matters:\n  If people fear blame, they hide information \u2192 slower incident response\n  If people are safe to be honest, you get the FULL story \u2192 real root cause found\n  \"Human error\" is rarely the root cause \u2014 it's usually a symptom of a system\n  that made the error easy to make\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"error-budgets-sre-concept",children:"Error Budgets (SRE Concept)"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"An error budget is the acceptable amount of unreliability, derived from your SLO.\n\nExample:\n  SLO: 99.9% uptime per month (this is your target)\n  Error budget: 0.1% = ~43 minutes of downtime allowed per month\n\nHow it's used:\n  Budget remaining \u2192 ship features fast, take more risks\n  Budget exhausted \u2192 freeze feature releases, focus entirely on reliability\n\nThis turns reliability into a SHARED, QUANTIFIED goal between Dev and Ops:\n  Dev wants to ship features (uses budget)\n  Ops wants stability (protects budget)\n  The error budget makes this a data-driven negotiation, not a political one\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"shift-left",children:"Shift-Left"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'"Shifting left" means moving a practice EARLIER in the development lifecycle\n(further left on the Plan\u2192Code\u2192Build\u2192Test\u2192Release\u2192Deploy\u2192Operate\u2192Monitor timeline)\n\nShift-left testing:\n  Old: QA tests after development is "done"\n  New: automated tests run on every commit; developers write tests as they code\n\nShift-left security ("DevSecOps"):\n  Old: security review happens right before release (or after an incident)\n  New: static analysis (SAST), dependency scanning, and secret scanning run\n        in CI on every pull request\n\nShift-left cost/FinOps:\n  Old: finance discovers cloud costs at the end of the month\n  New: cost estimates shown in pull requests before infrastructure is deployed\n        (e.g. Infracost for Terraform)\n\nWhy it matters:\n  A bug caught in code review costs minutes to fix\n  The same bug caught in production costs hours (incident response) + reputation\n  Shifting left doesn\'t eliminate problems \u2014 it catches them cheaper and earlier\n'})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"DORA metrics are the industry-standard way to talk about DevOps maturity in interviews and performance reviews \u2014 know all four cold."}),"\n",(0,r.jsx)(n.li,{children:"Blameless postmortems only work if leadership genuinely doesn't punish people for honest incident reports \u2014 this has to be a real cultural commitment, not just a document template."}),"\n",(0,r.jsx)(n.li,{children:'"You build it, you run it" (Amazon\'s phrase) is the practical embodiment of DevOps culture \u2014 the team that writes the code also carries the pager for it.'}),"\n",(0,r.jsx)(n.li,{children:'Error budgets resolve the eternal Dev-vs-Ops tension about "ship fast" vs "stay stable" by making it a shared, numeric, negotiated target.'}),"\n"]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"CALMS: Culture, Automation, Lean, Measurement, Sharing \u2014 the five pillars of DevOps."}),"\n",(0,r.jsx)(n.li,{children:"DORA metrics: deployment frequency, lead time for changes, change failure rate, time to restore service."}),"\n",(0,r.jsx)(n.li,{children:"DevOps is a philosophy; SRE is Google's software-engineering implementation of it; Platform Engineering productises it internally."}),"\n",(0,r.jsx)(n.li,{children:"The Three Ways: Flow (fast left-to-right), Feedback (fast right-to-left), Continual Learning."}),"\n",(0,r.jsx)(n.li,{children:"Blameless postmortems focus on systemic root causes, not individual blame \u2014 use the 5 Whys technique."}),"\n",(0,r.jsx)(n.li,{children:'Error budgets quantify acceptable unreliability, turning "ship fast vs stay stable" into a data-driven tradeoff.'}),"\n",(0,r.jsx)(n.li,{children:"Shift-left: move testing, security, and cost analysis earlier in the pipeline \u2014 cheaper to fix problems early."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>o,x:()=>a});var s=t(6540);let r={},i=s.createContext(r);function o(e){let n=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),s.createElement(i.Provider,{value:n},e.children)}}}]);